```typescript
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { Checkout } from './Checkout';
import { CartProvider } from './CartContext';
import { PaymentProvider } from './PaymentContext';

const mockItems = [
  { id: '1', name: 'Widget', price: 29.99 },
  { id: '2', name: 'Gadget', price: 49.99 }
];

const renderCheckout = (cartItems = mockItems, processPayment = vi.fn()) => {
  return render(
    <CartProvider initialItems={cartItems}>
      <PaymentProvider processPayment={processPayment}>
        <Checkout onComplete={vi.fn()} onCancel={vi.fn()} />
      </PaymentProvider>
    </CartProvider>
  );
};

describe('Checkout Component - The Device For Exchanging Currency', () => {
  describe('Happy Path - When Everything Goes Magnificently Right', () => {
    it('completes full checkout flow from shipping to confirmation', async () => {
      const user = userEvent.setup();
      const mockProcess = vi.fn().mockResolvedValue({ orderId: 'ORD-123' });
      renderCheckout(mockItems, mockProcess);

      // Shipping step
      await user.type(screen.getByLabelText(/street address/i), '123 Main St');
      await user.type(screen.getByLabelText(/city/i), 'Ankh-Morpork');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '90210');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'Leonard of Quirm');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review step
      expect(screen.getByText(/widget/i)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation
      await waitFor(() => {
        expect(screen.getByRole('status')).toHaveTextContent('ORD-123');
      });
    });
  });

  describe('Validation - The Mechanism For Catching Mistakes', () => {
    it('displays error for invalid ZIP code format', async () => {
      const user = userEvent.setup();
      renderCheckout();

      await user.type(screen.getByLabelText(/zip code/i), 'ABCDE');
      await user.click(screen.getByRole('button', { name: /continue/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/valid zip/i);
      expect(screen.getByLabelText(/zip code/i)).toHaveAttribute('aria-invalid', 'true');
    });
  });

  describe('Empty Cart - The Absence of Things To Purchase', () => {
    it('shows empty cart message and prevents checkout', () => {
      renderCheckout([]);

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
      expect(screen.getByRole('button', { name: /continue shopping/i })).toBeInTheDocument();
    });
  });

  describe('Payment Failure - When The Money Device Says No', () => {
    it('displays error and allows retry on payment failure', async () => {
      const user = userEvent.setup();
      const mockProcess = vi.fn().mockRejectedValueOnce(new Error('Card declined'));
      // ... navigate to review step ...

      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
      });
      expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
    });
  });
});
